-- Run against an isolated Postgres with the migration applied. Entire fixture is rolled back.
begin;
insert into public.articles(url,title,html,rewrite_mode,source_api_url,opinion) values('https://en.wikipedia.org/wiki/Legacy','Old article','<p>Preserved cache</p>','llm','https://en.wikipedia.org/w/api.php','Stance') on conflict(url) do nothing;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception '%',message; end if; end $$;
select pg_temp.assert(not has_table_privilege('anon','public.article_jobs','select'),'Anon must not read private job state');
select pg_temp.assert(not has_table_privilege('authenticated','public.article_jobs','insert'),'Authenticated must not write jobs');
select pg_temp.assert(not has_table_privilege('anon','public.articles','insert'),'Anon must not poison shared cache');
select pg_temp.assert(has_table_privilege('anon','public.articles','select'),'Legacy public reads must remain');
select pg_temp.assert(not exists(select 1 from pg_proc p join pg_namespace n on p.pronamespace=n.oid where n.nspname='public' and p.proname in ('take_rate_budget','claim_provider_slot','release_provider_slot','admit_article_job','claim_article_job','checkpoint_article_job','finish_article_job','release_article_job','retry_article_job','next_article_wake') and has_function_privilege('anon',p.oid,'execute')),'All privileged RPCs must deny anon');
set local role service_role;
select pg_temp.assert(public.take_rate_budget('test:rate',2,60),'First rate allocation');
select pg_temp.assert(public.take_rate_budget('test:rate',2,60),'Second rate allocation');
select pg_temp.assert(not public.take_rate_budget('test:rate',2,60),'Rate allocation bounded');
do $$ declare i int; begin for i in 1..8 loop perform pg_temp.assert(public.claim_provider_slot(gen_random_uuid(),35),'Eight provider slots available'); end loop; perform pg_temp.assert(not public.claim_provider_slot(gen_random_uuid(),35),'Ninth provider slot denied'); end $$;
reset role;
update public.article_provider_slots set expires_at=clock_timestamp()-interval '1 second' where owner=(select owner from public.article_provider_slots limit 1);
set local role service_role;
select pg_temp.assert(public.claim_provider_slot('00000000-0000-4000-8000-000000000099',35),'Expired provider slot recovers');
select public.release_provider_slot('00000000-0000-4000-8000-000000000099');
select pg_temp.assert(public.claim_provider_slot('00000000-0000-4000-8000-000000000099',35),'Released provider slot recovers');
reset role;
do $$
declare j1 jsonb; j2 jsonb; j3 jsonb; duplicate jsonb; first_claim jsonb; second_claim jsonb; renewed jsonb; owner1 uuid:=gen_random_uuid(); owner2 uuid:=gen_random_uuid(); owner3 uuid:=gen_random_uuid(); jid uuid; at timestamptz;
begin
  j1:=public.admit_article_job(jsonb_build_object('id',gen_random_uuid(),'url','https://en.wikipedia.org/wiki/SqlA','version','test-v1','lang','en','title','A','status','queued','outputs','{}'::jsonb,'plan',jsonb_build_object('blocks',jsonb_build_array(jsonb_build_object('id','b1'),jsonb_build_object('id','b2'))),'failures','{}'::jsonb,'metrics','{}'::jsonb),'aliasA','clientA',true);
  duplicate:=public.admit_article_job(jsonb_build_object('id',gen_random_uuid(),'url','https://en.wikipedia.org/wiki/SqlA','version','test-v1'),'aliasMobileA','clientA',true);
  perform pg_temp.assert(j1->>'id'=duplicate->>'id','Canonical duplicate returns same job');
  j2:=public.admit_article_job(jsonb_build_object('id',gen_random_uuid(),'url','https://en.wikipedia.org/wiki/SqlB','version','test-v1','lang','en','title','B','status','queued','outputs','{}'::jsonb,'failures','{}'::jsonb),'aliasB','clientA',true);
  j3:=public.admit_article_job(jsonb_build_object('id',gen_random_uuid(),'url','https://en.wikipedia.org/wiki/SqlC','version','test-v1','lang','en','title','C','status','queued','outputs','{}'::jsonb,'failures','{}'::jsonb),'aliasC','clientB',true);
  first_claim:=public.claim_article_job(owner1); second_claim:=public.claim_article_job(owner2);
  perform pg_temp.assert(first_claim is not null and second_claim is not null,'Two worker claims available');
  perform pg_temp.assert(public.claim_article_job(owner3) is null,'Third worker denied');
  jid:=(first_claim->>'id')::uuid;
  perform public.checkpoint_article_job(jid,owner1,'{}','{"b1":"first saved output"}');
  at:=(select updated_at from public.article_jobs where id=jid);
  perform public.checkpoint_article_job(jid,owner1,'{}','{"b2":"second saved output"}');
  perform pg_temp.assert((select state->'outputs' from public.article_jobs where id=jid)='{"b1":"first saved output","b2":"second saved output"}'::jsonb,'Checkpoints merge by block ID');
  perform pg_temp.assert((select completed=2 and total=2 and updated_at>at from public.article_jobs where id=jid),'Counts and timestamps updated');
  update public.article_jobs set lease_expires_at=clock_timestamp()-interval '1 second' where id=jid;
  update public.article_worker_slots set expires_at=clock_timestamp()-interval '1 second' where owner=owner1;
  renewed:=public.claim_article_job(owner3);
  perform pg_temp.assert(renewed->>'id'=jid::text,'Expired worker resumes same job');
  begin perform public.checkpoint_article_job(jid,owner1,'{}','{"b1":"stale overwrite"}'); raise exception 'Stale writer unexpectedly accepted'; exception when sqlstate 'P0002' then null; end;
  perform public.release_article_job(jid,owner1,clock_timestamp());
  perform pg_temp.assert((select lease_token=owner3 from public.article_jobs where id=jid),'Stale release cannot release current owner');
  perform public.finish_article_job(jid,owner3,'{"status":"complete","retryable":false}',null);
  perform pg_temp.assert(public.retry_article_job(jid)->>'status'='complete','Complete retry is a cache hit');
  perform pg_temp.assert((select state->'metrics'?'elapsedMs' from public.article_jobs where id=jid),'Finish persists measured elapsed time');
  jid:=(second_claim->>'id')::uuid;
  perform public.checkpoint_article_job(jid,owner2,'{"failures":{"b2":{"terminal":true}}}','{"b1":"saved"}');
  perform public.finish_article_job(jid,owner2,'{"status":"partial","retryable":true}',null);
  update public.article_generation_limits set max_queued=1 where singleton;
  begin perform public.retry_article_job(jid); raise exception 'Overfull retry unexpectedly admitted'; exception when sqlstate 'P0003' then null; end;
  update public.article_generation_limits set max_queued=20 where singleton;
  j2:=public.retry_article_job(jid);
  perform pg_temp.assert(j2->>'status'='queued' and j2->'state'->'outputs'='{"b1":"saved"}'::jsonb and j2->'state'->'failures'='{}'::jsonb,'Retry preserves outputs and clears only failure state');
end $$;
select pg_temp.assert((select count(*)=1 from public.articles where url='https://en.wikipedia.org/wiki/Legacy'),'Legacy rows preserved');
rollback;
